import{_ as s,a0 as l,w as p,s as h,ao as i,I as o,x as t,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"OnionShare：匿名共享文件 | LCTT x X-CMD","titleTemplate":false,"description":"OnionShare：匿名共享文件 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OnionShare：匿名共享文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OnionShare：匿名共享文件 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171208 OnionShare - Share Files Anonymously","title":"OnionShare：匿名共享文件","tag":"201712","desc":""},"relativePath":"201712/20171208 OnionShare - Share Files Anonymously.md","filePath":"[post].md"}'),d={name:"201712/20171208 OnionShare - Share Files Anonymously.md"};function u(f,n,w,m,S,g){const e=l("Link");return p(),h("div",null,[n[22]||(n[22]=i('<h1 id="onionshare-匿名共享文件" tabindex="-1">OnionShare：匿名共享文件 <a class="header-anchor" href="#onionshare-匿名共享文件" aria-label="Permalink to “OnionShare：匿名共享文件”">​</a></h1><p><img src="http://www.theitstuff.com/wp-content/uploads/2017/12/OnionShare-Share-Files-Anonymously.jpg" alt=""></p><p>在这个数字世界中，我们通过互联网使用 Dropbox、Mega、Google Drive 等不同云存储分享我们的媒体、文档和重要文件。但是每个云存储都有两个主要问题，一个是大小和另一个安全。习惯 Bit Torrent 之后，大小已经不是问题了，但安全性仍旧是。</p><p>你即使通过安全的云服务发送文件，该公司也会注意到这些文件，如果这些文件是保密的，政府甚至可以拿到它们。因此，为了克服这些问题，我们使用 OnionShare，如它的名字那样它使用洋葱网络也就是 Tor 来匿名分享文件给任何人。</p><h3 id="如何使用-onionshare" tabindex="-1">如何使用 <strong>OnionShare</strong>？ <a class="header-anchor" href="#如何使用-onionshare" aria-label="Permalink to “如何使用 OnionShare？”">​</a></h3>',5)),o("p",null,[n[2]||(n[2]=t("首先下载 ",-1)),r(e,{href:"https://onionshare.org/"},{default:a(()=>[...n[0]||(n[0]=[t("OnionShare",-1)])]),_:1}),n[3]||(n[3]=t(" 和 ",-1)),r(e,{href:"https://www.torproject.org/projects/torbrowser.html.en"},{default:a(()=>[...n[1]||(n[1]=[t("Tor浏览器",-1)])]),_:1}),n[4]||(n[4]=t("。下载后安装它们。",-1))]),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/Icons.png"},{default:a(()=>[...n[5]||(n[5]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/Icons.png",alt:"install onionshare and tor browser"},null,-1)])]),_:1})]),n[23]||(n[23]=o("p",null,"现在从开始菜单打开 OnionShare",-1)),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/Onion-Share.png"},{default:a(()=>[...n[6]||(n[6]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/Onion-Share.png",alt:"onionshare share files anonymously"},null,-1)])]),_:1})]),n[24]||(n[24]=o("p",null,"点击添加并添加一个文件/文件夹共享。",-1)),n[25]||(n[25]=o("p",null,"点击开始分享。它会产生一个 .onion 网址，你可以与你的收件人分享这个网址。",-1)),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/With-Link.png"},{default:a(()=>[...n[7]||(n[7]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/With-Link.png",alt:"share file with onionshare anonymously"},null,-1)])]),_:1})]),n[26]||(n[26]=o("p",null,"从 URL 下载文件，复制 URL 并打开 Tor 浏览器并粘贴。打开 URL 并下载文件/文件夹。",-1)),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/Tor.png"},{default:a(()=>[...n[8]||(n[8]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/Tor.png",alt:"receive file with onionshare anonymously"},null,-1)])]),_:1})]),n[27]||(n[27]=i('<h3 id="onionshare-的起源" tabindex="-1">OnionShare 的起源 <a class="header-anchor" href="#onionshare-的起源" aria-label="Permalink to “OnionShare 的起源”">​</a></h3><p>几年前，Glenn Greenwald 发现他从 Edward Snowden 收到的一些 NSA 的文件已经被损坏。但他需要该文件，并决定通过使用 USB 获取那些文件。这并不成功。</p><p>在阅读了 Greenwald 写的书后，The Intercept 的安全专家 Micah Lee 发布了 OnionShare —— 一个简单的免费软件，可以匿名和安全地共享文件。他创建了一个程序，通过一个被匿名软件 Tor 加密和保护的直接通道来分享大型数据转储，使窃取者难以获取文件。</p><h3 id="onionshare-如何工作" tabindex="-1">OnionShare 如何工作？ <a class="header-anchor" href="#onionshare-如何工作" aria-label="Permalink to “OnionShare 如何工作？”">​</a></h3><p>OnionShare 在 127.0.0.1 上启动了一个 Web 服务器，用于在随机端口上共享文件。它从有 6880 个单词的单词列表中选择任意两个单词，称为 slug。它使服务器可以作为 Tor 洋葱服务发送文件。最终的 URL 看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://qx2d7lctsnqwfdxh.onion/subside-durable</span></span></code></pre></div><p>OnionShare 在下载后关闭。有一个选项允许多次下载文件。这使得该文件在互联网上不能再次得到。</p><h3 id="使用-onionshare-好处" tabindex="-1">使用 OnionShare 好处 <a class="header-anchor" href="#使用-onionshare-好处" aria-label="Permalink to “使用 OnionShare 好处”">​</a></h3><p>其他网站或程序可以访问你的文件：发件人使用 OnionShare 共享的文件不存储在任何服务器上。它直接托管在发件人的系统上。</p><p>没有人可以窥探共享文件：由于用户之间的连接是由洋葱服务和 Tor 浏览器加密的。这使得连接安全，很难窃取文件。</p><p>用户双方都是匿名的：OnionShare 和 Tor 浏览器使发件人和收件人匿名。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>在这篇文章中，我已经解释了如何<strong>匿名分享你的文档、文件</strong>。我也解释了它是如何工作的。希望你了解 OnionShare 是如何工作的，如果你对任何事情仍有疑问，只需留言。</p><hr>',14)),o("p",null,[n[10]||(n[10]=t("via: ",-1)),r(e,{href:"https://www.theitstuff.com/onionshare-share-files-anonymously-2"},{default:a(()=>[...n[9]||(n[9]=[t("https://www.theitstuff.com/onionshare-share-files-anonymously-2",-1)])]),_:1})]),o("p",null,[n[14]||(n[14]=t("作者：",-1)),r(e,{href:"https://www.theitstuff.com"},{default:a(()=>[...n[11]||(n[11]=[t("Anirudh Rayapeddi",-1)])]),_:1}),n[15]||(n[15]=t(" 译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:a(()=>[...n[12]||(n[12]=[t("geekpi",-1)])]),_:1}),n[16]||(n[16]=t(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:a(()=>[...n[13]||(n[13]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[19]||(n[19]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...n[17]||(n[17]=[t("LCTT",-1)])]),_:1}),n[20]||(n[20]=t(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:a(()=>[...n[18]||(n[18]=[t("Linux中国",-1)])]),_:1}),n[21]||(n[21]=t(" 荣誉推出",-1))])])}const y=s(d,[["render",u]]);export{b as __pageData,y as default};
